const RX_NESTED = String.raw`\([^()]*[+*|][^()]*\)\s*[+*{]|\(\.\*\)|(\.\*){2,}`
const TEXT_MAX = 400
const BOOK_SCOPES: readonly string[] = ['all_org', 'explicit']
