      p === 44 || p === 45 ? 'shut' : p >= 20 && p < 30 ? 'left' : p >= 30 && p < 40 ? 'right' : 'open'
    yield S({ lift: DOZE, eyes, ears: [62, 63, 67, 68].includes(p) })
  }
